package httpserver

import (
	"io"
	"net/http"
	"strings"
)

func renderOverview(w http.ResponseWriter, production bool) {
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	page := designDemoPage
	if production {
		page = productionWorkspacePage
	}
	_, _ = io.WriteString(w, page)
}

func demoScript(production bool) http.HandlerFunc {
	return func(w http.ResponseWriter, _ *http.Request) {
		w.Header().Set("Content-Type", "application/javascript; charset=utf-8")
		script := designDemoJavaScript
		if production {
			script = productionWorkspaceJavaScript
		}
		_, _ = io.WriteString(w, script)
	}
}

func productionDemoPage() string {
	replacer := strings.NewReplacer(
		"<title>设计协同</title>", "<title>生产交付</title>",
		"<b>DO</b><strong>设计协同</strong>", "<b>PO</b><strong>生产交付</strong>",
		"<small>设计工作区</small>", "<small>生产工作区</small>",
		"设计协同引用 Project、People 与 Evidence 的稳定事实", "生产交付引用 Project、People 与 Evidence 的稳定事实",
		"Design Operations", "Production Operations",
		"看见设计工作真正推进到了哪里。", "看见每一种生产工作真正推进到了哪里。",
		"围绕 Project 管理四个设计阶段、阶段责任和成果文件。", "围绕 Project 分别管理设计、咨询等版本化生产类型、阶段责任和成果文件。",
		"只接受有效、包含 design 类型的 Project。", "只接受有效、明确选择对应生产类型的 Project。",
		"设计工作项", "生产工作项",
		"选择一个设计工作项", "选择一个生产工作项",
		"设置设计负责人", "设置生产负责人",
		"引用一个 design Project", "引用 Project 并选择生产类型",
		"<label>Project ID", "<label>生产类型<select name=\"type_key\"><option value=\"design-v1\">设计 design-v1</option><option value=\"consultation-v1\">咨询 consultation-v1</option></select></label><label>Project ID",
		"<script src=\"/assets/demo.js\">", "<script src=\"assets/demo.js\">",
	)
	return replacer.Replace(designDemoPage)
}

func productionDemoJavaScript() string {
	script := strings.NewReplacer(
		"design-demo-token", "production-demo-token",
		"/api/v1/design-work-items", "api/v1/production-work-items",
		"if(!state.token)throw new Error('请先设置访问凭证');const headers={Authorization:'Bearer '+state.token,...(opt.headers||{})}", "const headers={...(opt.headers||{})};if(state.token)headers.Authorization='Bearer '+state.token",
		"<strong>设计工作项</strong>", "<strong>生产工作项</strong>",
		"$('#itemTitle').textContent='设计工作项'", "$('#itemTitle').textContent='生产工作项 · '+w.type_key",
		"project_source_revision:Number(f.get('project_source_revision'))", "project_source_revision:Number(f.get('project_source_revision')),type_key:f.get('type_key')",
		";if(state.token){$('#authState').textContent='凭证已保存在当前标签页';load()}})();", ";if(state.token){$('#authState').textContent='凭证已保存在当前标签页'}else{$('#authState').textContent='统一入口已连接'}load()})();",
	).Replace(designDemoJavaScript)
	return script
}

const designDemoPage = `<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>设计协同</title><style>` + designDemoCSS + `</style></head><body><header><a href="/" class="brand"><b>DO</b><strong>设计协同</strong></a><div><span id="authState">尚未连接</span><button id="authButton" class="secondary">设置访问凭证</button></div></header><div class="app"><nav><small>设计工作区</small><button class="nav active" data-page="overview">概览</button><button class="nav" data-page="work">工作项</button><p><strong>边界说明</strong>设计协同引用 Project、People 与 Evidence 的稳定事实，不复制它们的领域模型。</p></nav><main>
<section id="overview" class="page active"><div class="hero"><p class="kicker">Design Operations</p><h1>看见设计工作真正推进到了哪里。</h1><p>围绕 Project 管理四个设计阶段、阶段责任和成果文件。完成与重开都留下可验证历史。</p><button class="primary" data-open="work">打开工作项</button></div><div class="steps"><article><b>01</b><h2>引用 Project</h2><p>只接受有效、包含 design 类型的 Project。</p></article><article><b>02</b><h2>装配负责人和成果</h2><p>负责人来自 People，成果来自 Evidence。</p></article><article><b>03</b><h2>推进阶段门槛</h2><p>缺少责任或成果时失败关闭，并明确说明。</p></article></div></section>
<section id="work" class="page"><div class="title"><div><p class="kicker">Work Items</p><h1>设计工作项</h1></div><button id="refresh" class="secondary">刷新</button></div><div id="notice" class="notice">设置访问凭证后读取工作项。</div><div class="columns"><section class="panel"><div class="panel-title"><h2>工作项</h2><button id="newItem" class="primary">新建</button></div><div id="itemList" class="list"><div class="empty">尚未读取数据。</div></div></section><section class="panel workspace"><div id="blank" class="empty focus"><strong>选择一个设计工作项</strong><span>查看阶段、负责人、成果和历史。</span></div><div id="details" hidden><div class="detail-head"><div><span id="status" class="pill"></span><h2 id="itemTitle"></h2><code id="itemID"></code></div><button id="reload" class="secondary">重新载入</button></div><dl><div><dt>Project</dt><dd id="projectID"></dd></div><div><dt>Revision</dt><dd id="revision"></dd></div><div><dt>当前阶段</dt><dd id="currentStage"></dd></div></dl><div class="tabs"><button class="tab active" data-pane="stages">阶段</button><button class="tab" data-pane="owner">负责人</button><button class="tab" data-pane="history">历史</button></div>
<section id="stages" class="pane active"><div id="stageList" class="stage-list"></div><form id="deliverableForm" class="form"><h3>登记阶段成果</h3><label>阶段<select name="stage_key"><option value="scheme">方案</option><option value="preliminary-design">初步设计</option><option value="construction-drawing">施工图</option><option value="construction-support">施工配合</option></select></label><label>Evidence File ID<input name="evidence_file_id" required placeholder="文件 UUID"></label><label>File version<input name="evidence_version" type="number" min="1" value="1" required></label><label>Evidence revision<input name="evidence_source_revision" type="number" min="1" value="1" required></label><button class="primary">登记成果</button></form></section>
<section id="owner" class="pane"><form id="ownerForm" class="form"><h3>设置设计负责人</h3><p>先在 Project Workspace 装配生产负责人，再填写 Assignment ID 与 revision。</p><label>Assignment ID<input name="assignment_id" required placeholder="Assignment UUID"></label><label>Assignment revision<input name="assignment_source_revision" type="number" min="1" value="1" required></label><button class="primary">设置负责人</button></form></section>
<section id="history" class="pane"><div class="pane-title"><h3>不可覆盖的业务历史</h3><button id="loadHistory" class="secondary">读取</button></div><div id="historyList" class="timeline"></div></section></div></section></div></section></main></div>
<dialog id="authDialog"><form id="authForm" method="dialog"><p class="kicker">访问控制</p><h2>连接业务 API</h2><p>粘贴本地模板 Token 或 IAM 短期 Capability Credential。凭证只保存在当前标签页。</p><label>Bearer Token<textarea id="token" rows="5" required></textarea></label><footer><button value="cancel" class="secondary">取消</button><button class="primary">保存并连接</button></footer></form></dialog>
<dialog id="createDialog"><form id="createForm" method="dialog"><p class="kicker">新建工作项</p><h2>引用一个 design Project</h2><label>Project ID<input name="project_id" required placeholder="Project UUID"></label><label>Project revision<input name="project_source_revision" type="number" min="1" value="1" required></label><footer><button value="cancel" class="secondary">取消</button><button class="primary">建立工作项</button></footer></form></dialog><script src="assets/demo.js"></script></body></html>`

const designDemoCSS = `:root{font-family:Inter,"PingFang SC","Microsoft YaHei",system-ui,sans-serif;color:#182235;background:#f4f5f7;--muted:#667085;--line:#d9dee7;--soft:#f7f9fb;--accent:#215aa8;--nav:#15365f}*{box-sizing:border-box}body{margin:0}header{height:64px;display:flex;align-items:center;justify-content:space-between;padding:0 28px;background:#fff;border-bottom:1px solid var(--line);position:sticky;top:0;z-index:5}header>div{display:flex;align-items:center;gap:12px;color:var(--muted);font-size:13px}.brand{display:flex;align-items:center;gap:11px;color:inherit;text-decoration:none}.brand b{display:grid;width:34px;height:34px;place-items:center;border-radius:7px;background:var(--nav);color:white;font-size:12px}.app{display:grid;grid-template-columns:220px 1fr;min-height:calc(100vh - 64px)}nav{padding:26px 18px;background:#fff;border-right:1px solid var(--line)}nav small,.kicker{display:block;margin:0 0 9px;color:var(--accent);font-size:11px;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.nav{display:block;width:100%;padding:11px 13px;border:0;border-left:3px solid transparent;background:transparent;text-align:left;color:#4d596b;font:inherit;cursor:pointer}.nav.active{border-color:var(--accent);background:#edf3fb;color:var(--accent);font-weight:750}nav p{display:grid;gap:5px;margin-top:32px;padding:14px;border-top:1px solid var(--line);color:var(--muted);font-size:12px}main{min-width:0;padding:30px}.page{display:none}.page.active{display:block}.hero{min-height:340px;padding:54px;border:1px solid var(--line);border-radius:12px;background:linear-gradient(120deg,#fff 65%,#e8eff8)}h1,h2,h3,p{margin-top:0}.hero h1{max-width:760px;margin-bottom:18px;font-size:clamp(34px,5vw,58px);line-height:1.07;letter-spacing:-.045em}.hero>p:not(.kicker){max-width:680px;color:var(--muted);font-size:17px}.steps{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;margin-top:18px}.steps article,.panel{padding:21px;border:1px solid var(--line);border-radius:10px;background:#fff}.steps b{color:var(--accent)}.steps h2{margin:12px 0 5px;font-size:17px}.steps p{margin:0;color:var(--muted);font-size:13px}.primary,.secondary{padding:9px 13px;border:1px solid transparent;border-radius:6px;font:inherit;font-size:13px;font-weight:700;cursor:pointer}.primary{background:var(--accent);color:#fff}.secondary{border-color:var(--line);background:#fff;color:#414c5d}.title,.panel-title,.detail-head,.pane-title{display:flex;align-items:center;justify-content:space-between;gap:16px}.title{margin-bottom:18px}.title h1{margin:0}.notice{margin-bottom:14px;padding:11px 14px;border:1px solid #cad8ea;border-radius:7px;background:#eef4fb;color:#315477;font-size:13px}.notice.ok{border-color:#bce0cb;background:#eefaf3;color:#15623d}.notice.error{border-color:#efc6c6;background:#fff2f2;color:#9f2d2d}.columns{display:grid;grid-template-columns:330px 1fr;gap:16px}.panel{min-height:620px}.panel-title h2{margin:0;font-size:17px}.list{display:grid;gap:7px;margin-top:14px}.record{display:grid;gap:3px;padding:12px;border:1px solid var(--line);border-radius:7px;background:#fff;text-align:left;cursor:pointer}.record.active,.record:hover{border-color:#7da3cf;background:#f2f6fb}.record span,.record small{color:var(--muted)}.empty{display:grid;gap:5px;padding:24px;color:var(--muted);font-size:13px;text-align:center}.focus{min-height:420px;place-content:center}.detail-head{padding-bottom:16px;border-bottom:1px solid var(--line)}.detail-head h2{margin:6px 0 3px}.detail-head code{color:var(--muted);font-size:11px}.pill{display:inline-flex;padding:3px 8px;border-radius:99px;background:#e9eef5;font-size:11px;font-weight:800}dl{display:grid;grid-template-columns:2fr 1fr 1fr;gap:10px}dl div{padding:11px;border-radius:6px;background:var(--soft)}dt{color:var(--muted);font-size:11px}dd{margin:3px 0 0;font-size:13px}.tabs{display:flex;border-bottom:1px solid var(--line)}.tab{padding:10px 13px;border:0;border-bottom:2px solid transparent;background:transparent;color:var(--muted);font:inherit;cursor:pointer}.tab.active{border-color:var(--accent);color:var(--accent);font-weight:750}.pane{display:none;padding-top:18px}.pane.active{display:block}.stage-list{display:grid;gap:8px;margin-bottom:14px}.stage{display:grid;grid-template-columns:1fr auto auto;gap:10px;align-items:center;padding:12px;border:1px solid var(--line);border-radius:7px}.stage span{color:var(--muted);font-size:12px}.stage-actions{display:flex;gap:5px}.stage-actions button{padding:6px 8px}.form{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;padding:15px;border:1px solid var(--line);border-radius:8px;background:var(--soft)}.form h3,.form p{grid-column:1/-1}.form p{color:var(--muted);font-size:12px}label{display:grid;gap:5px;color:#4c5667;font-size:12px;font-weight:700}input,textarea,select{width:100%;padding:9px 10px;border:1px solid #cbd2dc;border-radius:5px;background:#fff;font:inherit}.timeline{display:grid;gap:9px;margin-top:12px}.event{padding:11px 13px;border-left:3px solid #90a9c7;background:var(--soft)}.event small{color:var(--muted)}dialog{width:min(540px,calc(100% - 32px));padding:25px;border:1px solid var(--line);border-radius:10px;box-shadow:0 24px 80px #15223833}dialog::backdrop{background:#14203699}dialog>form>p:not(.kicker){color:var(--muted);font-size:13px}dialog footer{display:flex;justify-content:flex-end;gap:9px;margin-top:18px}@media(max-width:960px){.app{grid-template-columns:1fr}nav{display:flex;padding:10px 18px;border-right:0;border-bottom:1px solid var(--line)}nav small,nav p{display:none}.nav{width:auto}.columns{grid-template-columns:1fr}.panel{min-height:auto}}@media(max-width:640px){header{padding:0 15px}header>div>span{display:none}main{padding:18px}.hero{padding:28px}.steps,dl,.form{grid-template-columns:1fr}.form h3,.form p{grid-column:auto}.stage{grid-template-columns:1fr}.stage-actions{flex-wrap:wrap}}`

const designDemoJavaScript = `(()=>{'use strict';const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],state={token:sessionStorage.getItem('design-demo-token')||'',items:[],details:null};const uuid=()=>crypto.randomUUID();
function note(m,t=''){const n=$('#notice');n.textContent=m;n.className='notice '+t}function page(id){$$('.page').forEach(x=>x.classList.toggle('active',x.id===id));$$('.nav').forEach(x=>x.classList.toggle('active',x.dataset.page===id))}function pane(id){$$('.pane').forEach(x=>x.classList.toggle('active',x.id===id));$$('.tab').forEach(x=>x.classList.toggle('active',x.dataset.pane===id))}
async function api(path,opt={}){if(!state.token)throw new Error('请先设置访问凭证');const headers={Authorization:'Bearer '+state.token,...(opt.headers||{})};if(opt.body)headers['Content-Type']='application/json';const r=await fetch(path,{...opt,headers}),text=await r.text();let data={};try{data=text?JSON.parse(text):{}}catch{throw new Error('服务返回内容无法识别')}if(!r.ok)throw new Error(data.error?.message||('请求失败 '+r.status));return data}
function record(x){const b=document.createElement('button');b.className='record'+(state.details?.work_item.id===x.id?' active':'');b.innerHTML='<strong>设计工作项</strong><span></span><small></small>';b.children[1].textContent=x.status+' · '+(x.current_stage_key||'未开始');b.children[2].textContent=x.project_id+' · r'+x.revision;b.onclick=()=>openItem(x.id);return b}
async function load(){try{note('正在读取工作项…');const d=await api('/api/v1/design-work-items?limit=50');state.items=d.items||[];const l=$('#itemList');l.replaceChildren();state.items.forEach(x=>l.append(record(x)));if(!l.children.length)l.innerHTML='<div class="empty">还没有设计工作项。</div>';note('已读取 '+state.items.length+' 个工作项。','ok')}catch(e){note(e.message,'error')}}
function render(){const d=state.details,w=d.work_item;$('#blank').hidden=true;$('#details').hidden=false;$('#status').textContent=w.status;$('#itemTitle').textContent='设计工作项';$('#itemID').textContent=w.id;$('#projectID').textContent=w.project_id;$('#revision').textContent=w.revision;$('#currentStage').textContent=w.current_stage_key||'未开始';const l=$('#stageList');l.replaceChildren();(d.stages||[]).forEach(s=>{const row=document.createElement('div');row.className='stage';const title=document.createElement('strong'),status=document.createElement('span'),actions=document.createElement('div');title.textContent=s.stage_key;status.textContent=s.status;actions.className='stage-actions';const complete=document.createElement('button');complete.className='primary';complete.textContent='完成';complete.onclick=()=>mutate('/api/v1/design-work-items/'+w.id+'/stages/'+s.stage_key+'/complete',{command_id:uuid(),expected_revision:state.details.work_item.revision});const reopen=document.createElement('button');reopen.className='secondary';reopen.textContent='重开';reopen.onclick=()=>mutate('/api/v1/design-work-items/'+w.id+'/stages/'+s.stage_key+'/reopen',{command_id:uuid(),expected_revision:state.details.work_item.revision,reason:'Demo 中重新打开阶段'});actions.append(complete,reopen);row.append(title,status,actions);l.append(row)});$('#itemList').replaceChildren(...state.items.map(record))}
async function openItem(id){try{note('正在读取工作区…');state.details=await api('/api/v1/design-work-items/'+id);render();note('工作区已同步。','ok')}catch(e){note(e.message,'error')}}async function mutate(path,body){try{note('正在提交业务动作…');await api(path,{method:'POST',body:JSON.stringify(body)});const id=state.details.work_item.id;await load();await openItem(id)}catch(e){note(e.message,'error')}}
$$('.nav').forEach(x=>x.onclick=()=>page(x.dataset.page));$$('[data-open]').forEach(x=>x.onclick=()=>page(x.dataset.open));$$('.tab').forEach(x=>x.onclick=()=>pane(x.dataset.pane));$('#authButton').onclick=()=>{$('#token').value=state.token;$('#authDialog').showModal()};$('#authForm').onsubmit=e=>{e.preventDefault();state.token=$('#token').value.trim();sessionStorage.setItem('design-demo-token',state.token);$('#authDialog').close();$('#authState').textContent='凭证已保存在当前标签页';load()};$('#refresh').onclick=load;$('#reload').onclick=()=>state.details&&openItem(state.details.work_item.id);$('#newItem').onclick=()=>$('#createDialog').showModal();
$('#createForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);try{const d=await api('/api/v1/design-work-items',{method:'POST',body:JSON.stringify({command_id:uuid(),project_id:f.get('project_id'),project_source_revision:Number(f.get('project_source_revision'))})});$('#createDialog').close();await load();await openItem(d.work_item.id)}catch(err){note(err.message,'error')}};
$('#ownerForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),w=state.details.work_item;mutate('/api/v1/design-work-items/'+w.id+'/owner',{command_id:uuid(),expected_revision:w.revision,assignment_id:f.get('assignment_id'),assignment_source_revision:Number(f.get('assignment_source_revision'))})};$('#deliverableForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),w=state.details.work_item;mutate('/api/v1/design-work-items/'+w.id+'/stages/'+f.get('stage_key')+'/deliverables',{command_id:uuid(),expected_revision:w.revision,requirement_key:'primary-output',evidence_file_id:f.get('evidence_file_id'),evidence_version:Number(f.get('evidence_version')),evidence_source_revision:Number(f.get('evidence_source_revision'))})};
$('#loadHistory').onclick=async()=>{try{const w=state.details.work_item,d=await api('/api/v1/design-work-items/'+w.id+'/history?limit=50'),l=$('#historyList');l.replaceChildren();(d.items||[]).forEach(x=>{const e=document.createElement('div');e.className='event';e.innerHTML='<strong></strong><br><small></small>';e.children[0].textContent=x.event_type;e.children[2].textContent='revision '+x.work_item_revision+' · '+new Date(x.occurred_at).toLocaleString('zh-CN');l.append(e)});if(!l.children.length)l.innerHTML='<div class="empty">没有历史记录。</div>';note('历史已读取。','ok')}catch(e){note(e.message,'error')}};if(state.token){$('#authState').textContent='凭证已保存在当前标签页';load()}})();`
